package com.example.crowdtransportfeedback.leaderboard;
import java.util.*; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class LeaderboardRankingTest {
 @Test void xpSortUsesUsernameTieBreakAndKeepsSeparateCurrentRankOutsideTop100(){UUID me=UUID.randomUUID();List<LeaderboardRanking.Candidate> rows=new ArrayList<>();for(int i=0;i<101;i++)rows.add(new LeaderboardRanking.Candidate(UUID.randomUUID(),String.format("user%03d",i),"COMMUTER",200-i,200-i));rows.add(new LeaderboardRanking.Candidate(me,"zzme","NAVIGATOR",1,1));var result=LeaderboardRanking.rank(rows,LeaderboardController.Metric.XP,LeaderboardController.Period.ALL_TIME,100,me);assertEquals(100,result.top().size());assertEquals(102,result.currentUser().rank());assertFalse(result.top().stream().anyMatch(LeaderboardController.Entry::currentUser));}
 @Test void achievementsUseXpThenUsernameAndCurrentUserRemainsInTop(){UUID me=UUID.randomUUID();var rows=List.of(new LeaderboardRanking.Candidate(UUID.randomUUID(),"beta","COMMUTER",3,100),new LeaderboardRanking.Candidate(me,"alpha","NAVIGATOR",3,100));var result=LeaderboardRanking.rank(rows,LeaderboardController.Metric.ACHIEVEMENTS,LeaderboardController.Period.ALL_TIME,100,me);assertEquals("alpha",result.top().getFirst().username());assertTrue(result.top().getFirst().currentUser());assertEquals(1,result.currentUser().rank());}
 @Test void monthlyZeroIsUnrankedAndExcludedFromTop(){UUID me=UUID.randomUUID();var result=LeaderboardRanking.rank(List.of(new LeaderboardRanking.Candidate(me,"zero","COMMUTER",0,120)),LeaderboardController.Metric.CONTRIBUTIONS,LeaderboardController.Period.THIS_MONTH,100,me);assertNull(result.currentUser().rank());assertTrue(result.top().isEmpty());}
}
